class Solution:
    def numberOfWays(self, startPos, endPos, k):
        MOD = 10**9 + 7
        d = abs(endPos - startPos)
        dp = [0] * (2 * k + 1)
        dp[k] = 1
        for _ in range(k):
            ndp = [0] * (2 * k + 1)
            for o in range(2 * k + 1):
                if dp[o]:
                    if o > 0: ndp[o - 1] = (ndp[o - 1] + dp[o]) % MOD
                    if o < 2 * k: ndp[o + 1] = (ndp[o + 1] + dp[o]) % MOD
            dp = ndp
        return dp[k + d] if abs(d) <= k else 0

