class Solution {
public:
    int numberOfWays(int startPos, int endPos, int k) {
        const long long MOD = 1e9 + 7;
        int d = abs(endPos - startPos);
        if (d > k) return 0;
        vector<long long> dp(2 * k + 1, 0);
        dp[k] = 1;
        for (int s = 0; s < k; s++) {
            vector<long long> ndp(2 * k + 1, 0);
            for (int o = 0; o <= 2 * k; o++) {
                if (!dp[o]) continue;
                if (o > 0) ndp[o-1] = (ndp[o-1] + dp[o]) % MOD;
                if (o < 2*k) ndp[o+1] = (ndp[o+1] + dp[o]) % MOD;
            }
            dp = ndp;
        }
        return dp[k + d];
    }
};

