class Solution {
public:
    int numberOfWays(int startPos, int endPos, int k) {
        const long long MOD = 1e9 + 7;
        long long d = abs(startPos - endPos);
        if (d > k || (k - d) % 2) return 0;
        long long r = (k + d) / 2, num = 1, den = 1;
        for (long long i = 0; i < r; i++) {
            num = num * ((k - i) % MOD) % MOD;
            den = den * ((i + 1) % MOD) % MOD;
        }
        long long inv = 1, b = den, e = MOD - 2;
        while (e) { if (e & 1) inv = inv * b % MOD; b = b * b % MOD; e >>= 1; }
        return num * inv % MOD;
    }
};

