class Solution {
    public int numberOfWays(int startPos, int endPos, int k) {
        final long MOD = 1000000007L;
        long d = Math.abs(startPos - endPos);
        if (d > k || (k - d) % 2 != 0) return 0;
        long r = (k + d) / 2, num = 1, den = 1;
        for (long i = 0; i < r; i++) {
            num = num * ((k - i) % MOD) % MOD;
            den = den * ((i + 1) % MOD) % MOD;
        }
        long inv = 1, b = den, e = MOD - 2;
        while (e > 0) { if ((e & 1) == 1) inv = inv * b % MOD; b = b * b % MOD; e >>= 1; }
        return (int)(num * inv % MOD);
    }
}

