    const MOD = 1e9 + 7, d = Math.abs(startPos - endPos);
    if (d > k || (k - d) % 2) return 0;
    let r = (k + d) / 2, num = 1n, den = 1n, B = BigInt(MOD);
    for (let i = 0n; i < BigInt(r); i++) {
        num = num * (BigInt(k) - i) % B;
        den = den * (i + 1n) % B;
    }
    const powmod = (b, e) => { let res = 1n; while (e) { if (e & 1n) res = res * b % B; b = b * b % B; e >>= 1n; } return res; };
    return Number(num * powmod(den, B - 2n) % B);
};
